import{_ as o,o as t,c as n,ae as a}from"./chunks/framework.sRTLHEzD.js";const s="/heidrun_code/screenshots/features/phone_access.png",f=JSON.parse('{"title":"The phone access","description":"From your phone, see the coding agents, allow or refuse a blocked request, send a prompt, and read the end of the output.","frontmatter":{"description":"From your phone, see the coding agents, allow or refuse a blocked request, send a prompt, and read the end of the output."},"headers":[],"relativePath":"features/phone_access.md","filePath":"features/phone_access.md"}'),r={name:"features/phone_access.md"};function i(h,e,c,d,l,u){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="the-phone-access" tabindex="-1">The phone access <a class="header-anchor" href="#the-phone-access" aria-label="Permalink to &quot;The phone access&quot;">​</a></h1><p>A coding agent can wait for an hour only for one permission, while you are away from your desk.</p><h2 id="what-heidrun-code-does" tabindex="-1">What Heidrun Code does <a class="header-anchor" href="#what-heidrun-code-does" aria-label="Permalink to &quot;What Heidrun Code does&quot;">​</a></h2><p>Heidrun Code serves a small web page from your computer. From your phone, you can:</p><ul><li>See the coding agents and their state, and find the ones that wait for a decision.</li><li>Allow or refuse the request of a blocked coding agent. The same guards as on your computer apply to a dangerous command.</li><li>Send a prompt to a coding agent, or interrupt a coding agent.</li><li>Read the end of the output of a coding agent.</li></ul><h2 id="safe-by-design" tabindex="-1">Safe by design <a class="header-anchor" href="#safe-by-design" aria-label="Permalink to &quot;Safe by design&quot;">​</a></h2><ul><li>Heidrun Code serves the page only on the loopback address of your computer, so no other device on your network reaches it. An ngrok tunnel gives the page a public HTTPS address, and the page answers only to the address of the tunnel.</li><li>The tunnel puts the page on the Internet, so the pairing key is the protection. Each request needs it, and ten wrong keys in a row lock the wrong keys for one minute. Each phone pairs once, with a QR code.</li><li>ngrok ends the encryption on its own servers, so ngrok can read the traffic of the tunnel, including the pairing key.</li><li>The address of the tunnel is fixed for your free ngrok account: it is the same each time that the tunnel opens, so each phone scans the QR code only once.</li><li>The first time that a phone opens the address, ngrok shows a warning page of its free plan. That page also shows the public network address of your computer. Tap the button &quot;Visit Site&quot;.</li><li>The QR code holds the pairing key. Do not show the QR code, and do not share it.</li><li>The button &quot;Revoke the paired devices&quot; makes every paired device scan the QR code again.</li><li>The tunnel opens when you turn the mobile access on, and closes when you turn it off or quit Heidrun Code.</li></ul><h2 id="set-up-the-phone-access" tabindex="-1">Set up the phone access <a class="header-anchor" href="#set-up-the-phone-access" aria-label="Permalink to &quot;Set up the phone access&quot;">​</a></h2><ol><li>Install the program <code>ngrok</code> on your computer. With Homebrew, run <code>brew install ngrok</code>.</li><li>Create a free account at ngrok.com, then run the command that its dashboard shows: <code>ngrok config add-authtoken &lt;your token&gt;</code>.</li><li>In Heidrun Code, open the section &quot;Mobile access&quot; of the Settings window, and click &quot;Turn on mobile access&quot;. Heidrun Code opens the tunnel by itself. This takes a few seconds.</li><li>Scan the QR code with the camera of the phone. The first time, tap the button &quot;Visit Site&quot;. The phone opens the page and is paired.</li></ol><p>To use the page in the web browser of your computer, click the address under the QR code in the Settings window. The page opens already paired.</p><p><img src="'+s+'" alt="The section &quot;Mobile access&quot; of the Settings window before the phone access is on: the switch &quot;Turn on mobile access&quot;, and the note about the ngrok tunnel."></p><p><em>Even Odin leaves Valhalla sometimes. Now the einherjar can still reach him.</em></p>',12)])])}const g=o(r,[["render",i]]);export{f as __pageData,g as default};
